import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
import styles from '../css/chat.module.css';

const Chat = () => {
  const location = useLocation();
  const { personality, name: chatbotName = '챗봇' } = location.state || {};
  const [userInput, setUserInput] = useState('');
  const [currentDateTime, setCurrentDateTime] = useState('');
  const [messages, setMessages] = useState([]);
  const chatEndRef = useRef(null);
  const [alertTime, setAlertTime] = useState(null);

  // 시간 추출 함수: 사용자 입력에서 '시간'과 '분'을 추출
  const extractTimeFromInput = (input) => {
    const regex = /(\d{1,2})시\s*(\d{1,2})분/;  // 예: "4시 40분", "6시 5분"
    const match = input.match(regex);

    if (match) {
      const hour = parseInt(match[1], 10);
      const minute = parseInt(match[2], 10);
      return { hour, minute };
    }
    return null;
  };

  // 알림 보내기
  const sendNotification = () => {
    alert('슬슬 수업 마칠 준비해야지!');
  };

  // 알림 시간 설정 (5분 전)
  const setAlertForUserSchedule = (hour, minute) => {
    const now = new Date();
    const alertTime = new Date(now);
    alertTime.setHours(hour, minute, 0, 0); // 사용자가 지정한 시간으로 설정

    // 알림 시간을 5분 전으로 설정
    const alertTime5MinutesBefore = new Date(alertTime.getTime() - 5 * 60 * 1000);

    const timeUntilAlert = alertTime5MinutesBefore.getTime() - now.getTime();
    const delay = timeUntilAlert > 0 ? timeUntilAlert : timeUntilAlert + 24 * 60 * 60 * 1000;

    // 알림 타이머 설정
    setTimeout(() => {
      sendNotification();
    }, delay);
  };

  // 사용자가 시간을 입력하면 알림 설정
  const handleUserInput = () => {
    const time = extractTimeFromInput(userInput);
    if (time) {
      setAlertForUserSchedule(time.hour, time.minute); // 알림 설정
    }

    // 메시지 기록에 추가
    setMessages((prevMessages) => [
      ...prevMessages,
      { sender: '사용자', message: userInput, time: new Date().toLocaleTimeString('ko-KR') },
    ]);
    setUserInput('');  // 입력 필드 초기화
  };

  // 채팅 기록 가져오기
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(new Date().toLocaleString('ko-KR'));
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // 채팅 기록에 변화가 있을 때 자동으로 스크롤
  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  return (
    <div className={styles.chatContainer}>
      <div className={styles.chatDataTime}>
        <strong>{currentDateTime}</strong>
      </div>
      <div className={styles.chatHistory}>
        {messages.map((msg, index) => (
          <div
            key={index}
            className={msg.sender === '사용자' ? styles.chatMessageUser : styles.chatMessageChatbot}
          >
            <strong>{msg.sender === '사용자' ? '사용자' : chatbotName}:</strong>
            <div>{msg.message}</div>
            <div className={msg.sender === '사용자' ? styles.chatTimeUser : styles.chatTimeChatbot}>
              <em>{msg.time}</em>
            </div>
          </div>
        ))}
        <div ref={chatEndRef} />
      </div>
      <div className={styles.chatInputArea}>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          placeholder="시간 입력 (예: 4시 40분)"
        />
        <button
          className={styles.chatSendButton}
          onClick={handleUserInput}
        >
          전송
        </button>
      </div>
    </div>
  );
};

export default Chat;
